Generated SQL:
SELECT p."customerNumber", p."checkNumber", p."paymentDate", p."amount", c."customerName"
FROM "payments" p
JOIN "customers" c ON p."customerNumber" = c."customerNumber";

SELECT p."productName", pl."productLine", pl."textDescription"
FROM "products" p
JOIN "productlines" pl ON p."productLine" = pl."productLine";

SELECT o."orderNumber", o."orderDate", o."requiredDate", o."shippedDate", o."status", o."comments", o."customerNumber", c."city"
FROM "orders" o
JOIN "customers" c ON o."customerNumber" = c."customerNumber";

SELECT od.*, p."productName", p."productVendor"
FROM "orderdetails" od
JOIN "products" p ON od."productCode" = p."productCode";

SELECT p."customerNumber", p."checkNumber", p."paymentDate", p."amount", c."country"
FROM "payments" p
JOIN "customers" c ON p."customerNumber" = c."customerNumber";
